/// Node example: prepare - Secret auth prepare emits REST request
/// 
/// Tests that node 'prepare' produces expected outputs for given inputs.
#[test]
fn test_example_prepare_secret_auth_prepare_emits_rest_request() {
    let dag = crate :: graph :: build_chat_completion_graph();
    let mut inputs = std::collections::HashMap::new();
    inputs.insert("messages".to_string(), Value::Str("Hello".to_string()));
    inputs.insert("model".to_string(), Value::Str("gpt-4o".to_string()));
    inputs.insert("provider".to_string(), Value::Str("openai".to_string()));
    let outputs = gunbc_exec::execute_single_node(&dag, "prepare", inputs, gunbc_exec::ExecutionMode::Real).expect("node 'prepare' should execute successfully");

    // Check output port 'provider'
    let output_provider = outputs.get("provider").expect("output port 'provider' should exist");
    assert!(!output_provider.is_empty(), "expected non-empty value");
    // Check output port 'request'
    let output_request = outputs.get("request").expect("output port 'request' should exist");
    assert!(!output_request.is_empty(), "expected non-empty value");
}

/// Node example: resolve_auth - Resolve auth maps OpenAI provider to API key env var
