    let dag = crate :: graph :: build_chat_completion_graph();
    let mut inputs = std::collections::HashMap::new();
    inputs.insert("provider".to_string(), Value::Str("openai".to_string()));
    let outputs = gunbc_exec::execute_single_node(&dag, "resolve_auth", inputs, gunbc_exec::ExecutionMode::Real).expect("node 'resolve_auth' should execute successfully");

    // Check output port 'env_var'
