    assert_eq!(*output_header_name, Value::Str("".to_string()), "expected exact value");
    // Check output port 'scheme'
    let output_scheme = outputs.get("scheme").expect("output port 'scheme' should exist");
    assert_eq!(*output_scheme, Value::Str("bearer".to_string()), "expected exact value");
    // Check output port 'service'
    let output_service = outputs.get("service").expect("output port 'service' should exist");
    assert_eq!(*output_service, Value::Str("openai".to_string()), "expected exact value");
